questionvariables.text:
/* Fixed: one specific proof. The best summary is second. */
ta1: [
 [sum_check, false, "Substitute \\(x = 1\\) into both sides. Each side equals \\(0\\), so the two sides are equal, and the proposition is proved."],
 [sum_rules, true, "Multiply out \\((x - 1)(x + 1)\\) using rules of algebra that hold for every real number. It simplifies to \\(x^2 - 1\\), so the two sides are equal whatever \\(x\\) is."],
 [sum_assume, false, "Assume that \\(x^2 - 1 = (x - 1)(x + 1)\\), then simplify both sides until they look the same, which shows that the assumption was true."],
 [sum_graph, false, "Draw the graphs of \\(y = x^2 - 1\\) and \\(y = (x - 1)(x + 1)\\). The graphs look exactly the same, so the two sides are equal for every \\(x\\)."]
];
